def summary(text):
    text = nltk.word_tokenize(text)
    filtered_text = [w for w in text if w not in stopwords.words("english")]
    stems = []
    for word in filtered_text:
    	stem = PorterStemmer().stem(word)
    	if stem not in stems:
    return " ".join(stems)


